ee:message.ee:set-payload:
%dw 2.0
output application/json

var telemetry = payload
var supportedMetrics = ["TEMPERATURE", "VIBRATION", "PRESSURE"]

fun classify(metric, value) =
    do {
        var metricName = upper(metric)
        var readingValue = value as Number
        var minValue = Mule::p("metrics." ++ metricName ++ ".min") as Number
        var maxValue = Mule::p("metrics." ++ metricName ++ ".max") as Number
        var warningValue = Mule::p("metrics." ++ metricName ++ ".warning") as Number
        var criticalValue = Mule::p("metrics." ++ metricName ++ ".critical") as Number
        ---
        if (readingValue < minValue or readingValue > maxValue)
            "OUT_OF_RANGE"
        else if (readingValue >= criticalValue)
            "CRITICAL"
        else if (readingValue >= warningValue)
            "WARNING"
        else
            "NORMAL"
    }

// Validate each reading independently
var assessedReadings =
    (telemetry.readings default []) map ((reading, index) ->
        do {
            var metric =
                if (reading is Object)
                    upper((reading.metricName default "") as String)
                else
                    ""

            var reason =
                if (!(reading is Object))
                    "Invalid reading object"
                else if (isEmpty(metric))
                    "Missing metric name"
                else if (!(reading.value is Number))
                    "Missing or invalid numeric value"
                else if (isEmpty((reading.unit default "") as String))
                    "Missing unit"
                else if (!contains(supportedMetrics, metric))
                    "Unsupported metric type"
                else
                    null
            ---
            {
                index: index,
                reading: reading,
                metric: metric,
                reason: reason
            }
        }
    )

var validReadings = assessedReadings filter ($.reason == null)
var rejectedReadings = assessedReadings filter ($.reason != null)

---
{
    deviceId: telemetry.deviceId,
    siteId: telemetry.siteId,
    firmwareVersion: telemetry.firmwareVersion,
    batchId: telemetry.batchId,
    correlationId: telemetry.correlationId,

    readings: validReadings map (item) -> {
        metricName: item.reading.metricName,
        value: item.reading.value,
        unit: item.reading.unit,
        readingTimestamp: item.reading.readingTimestamp,
        quality: item.reading.quality,
        status: classify(item.metric, item.reading.value)
    },

    readingCount: sizeOf(validReadings),

    rejectedCount: sizeOf(rejectedReadings),

    rejected: rejectedReadings map (item) -> {
        index: item.index,
        metricName: item.metric,
        reason: item.reason
    },

    processingStatus:
        if (sizeOf(validReadings) == 0 and sizeOf(rejectedReadings) > 0)
            "REJECTED"
        else if (sizeOf(rejectedReadings) > 0)
            "PARTIALLY_PROCESSED"
        else
            "PROCESSED",

    processedAt: now()
}
